import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"HYVE: Hybrid Views for LLM Context Engineering over Machine Data","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.05400","title":"HYVE: Hybrid Views for LLM Context Engineering over Machine Data","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.054,"authors":["Jian Tan","Fan Bu","Yuqing Gao","Dev Khanolkar","Jason Mackay","Boris Sobolev","Lei Jin","Li Zhang"],"domains":["cs.AI","context engineering"],"html":"https://arxiv.org/html/2604.05400v1","pdf_path":"pdfs/2604.05400.pdf","published_date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-07-hyve-hybrid-views-context-engineering-2604-05400.md","filePath":"research/papers/2026-04-07-hyve-hybrid-views-context-engineering-2604-05400.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-07-hyve-hybrid-views-context-engineering-2604-05400.md"};function i(s,e,l,d,c,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="hyve-hybrid-views-for-llm-context-engineering-over-machine-data" tabindex="-1">HYVE: Hybrid Views for LLM Context Engineering over Machine Data <a class="header-anchor" href="#hyve-hybrid-views-for-llm-context-engineering-over-machine-data" aria-label="Permalink to &quot;HYVE: Hybrid Views for LLM Context Engineering over Machine Data&quot;">​</a></h1><p><strong>Authors</strong>: Jian Tan, Fan Bu, Yuqing Gao, Dev Khanolkar, Jason Mackay, Boris Sobolev, Lei Jin, Li Zhang <strong>Published</strong>: April 07, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.05400" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.05400</a> · <a href="https://arxiv.org/html/2604.05400v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.05400 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.05400" target="_blank" rel="noreferrer">research/papers/pdfs/2604.05400.pdf</a> (22 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Machine data is central to observability and diagnosis in modern computing systems, appearing in logs, metrics, telemetry traces, and configuration snapshots. When provided to large language models (LLMs), this data typically arrives as a mixture of natural language and structured payloads such as JSON or Python/AST literals. Yet LLMs remain brittle on such inputs, particularly when they are long, deeply nested, and dominated by repetitive structure.</p><p>We present HYVE (HYbrid ViEw), a framework for LLM context engineering for inputs containing large machine-data payloads, inspired by database management principles. HYVE surrounds model invocation with coordinated preprocessing and postprocessing, centered on a request-scoped datastore augmented with schema information. During preprocessing, HYVE detects repetitive structure in raw inputs, materializes it in the datastore, transforms it into hybrid columnar and row-oriented views, and selectively exposes only the most relevant representation to the LLM. During postprocessing, HYVE either returns the model output directly, queries the datastore to recover omitted information, or performs a bounded additional LLM call for SQL-augmented semantic synthesis.</p><p>We evaluate HYVE on diverse real-world workloads spanning knowledge QA, chart generation, anomaly detection, and multi-step network troubleshooting. Across these benchmarks, HYVE reduces token usage by 50-90% while maintaining or improving output quality. On structured generation tasks, it improves chart-generation accuracy by up to 132% and reduces latency by up to 83%. Overall, HYVE offers a practical approximation to an effectively unbounded context window for prompts dominated by large machine-data payloads.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>HYVE framework</strong>：針對含大型 machine data（logs、metrics、telemetry traces、JSON/AST）的 LLM 輸入，設計 preprocessing + postprocessing 協調層，靈感來自 database management 原則。</li><li><strong>Request-scoped datastore</strong>：以 schema 增強的暫存資料庫為核心，在 model invocation 外圍進行結構偵測與物化，而非直接塞入 context window。</li><li><strong>Hybrid columnar/row-oriented views</strong>：自動偵測重複結構，轉換為混合欄位導向與行導向的 view，僅向 LLM 暴露最相關的表示形式，大幅壓縮 token 用量。</li><li><strong>SQL-augmented semantic synthesis</strong>：postprocessing 階段可直接查詢 datastore 補回省略資訊，或進行有界的額外 LLM call 做語意合成，避免資訊遺失。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>Token 用量降低 <strong>50–90%</strong>，跨 knowledge QA、chart generation、anomaly detection、multi-step network troubleshooting 四類真實工作負載皆維持或提升輸出品質。</li><li>Structured generation（chart generation）準確率提升最高 <strong>132%</strong>，延遲降低最高 <strong>83%</strong>。</li><li>整體效果：對以 machine data 為主的 prompt，實現近似「無界 context window」的實用近似。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文聚焦 machine data（結構化/半結構化），對純自然語言 prompt 的適用性未評估。</li><li>Request-scoped datastore 引入額外系統複雜度（schema 偵測、SQL 層），對低延遲要求場景的 overhead 未量化。</li><li>SQL-augmented postprocessing 需額外 LLM call，在 worst-case path 下可能抵消部分延遲增益。</li><li>評估集為公司內部真實工作負載，外部可重現性受限。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>NLAH 原則直接對應</strong>：HYVE 的「只暴露最相關表示給 LLM」與 <code>context-management.md</code> 的 NLAH 原則（Right context &gt; more context）高度一致，為該原則提供系統性工程實作的參考案例。</li><li><strong>The Loop OBSERVE 階段的 context 預算管理</strong>：HYVE 的 preprocessing datastore 可類比 The Loop 中 OBSERVE 前的「讀取最小必要範圍」紀律；token 50–90% 降幅為 token budget 軟性門檻（per-task ~4,000 tokens）在 machine data 場景的量化佐證。</li><li><strong>unverified_success 閘門的工具層類比</strong>：HYVE 的 postprocessing「query datastore to recover omitted information」階段，與 core.md <code>unverified_success</code> 閘門概念相似——model output 不直接信任，需機械查驗補回省略資訊後才確認結果。⚠️ 落地門檻：workspace 目前無 machine data ingestion pipeline，需額外基礎設施才能直接採用。</li><li><strong>Subagent context rot 緩解</strong>：fan-out 委派中各 sub-agent 收到的 context 若含大量結構化工具輸出（JSON logs），HYVE 式 view 壓縮可緩解 context rot 問題；⚠️ 目前 workspace 無此層，屬概念層連結。</li></ul>',16)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
